(function(){'use strict';if(typeof WebEngine==='undefined')return;const C=globalThis.NoirTRPG,E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stage={hazard:'도화선 · 긴급 대응 15초',gathering:'회관 대화 · 처음 40초',opening:'도입 이야기',small:'작은 행동 · 준비',plan:'행동 선택 · 공통 60초',clash:'행동 상황',settle:'결과 이야기 준비',react:'대결 · 대응',result:'행동의 결과',trial:'재판 대화 · 2분',vote:'최종 변론·표결 · 1분',consent:'재판 개정 동의',summons:'재판 소집',decision:'집계 결과',end:'이야기의 끝'};
class UI extends WebEngine.Component{
 start(){if(typeof document==='undefined')return;const link=document.createElement('link');link.rel='stylesheet';link.href='/project/assets/trpg.css';document.head.appendChild(link);this.root=document.createElement('main');this.root.id='noir';document.body.appendChild(this.root);this.sound=new globalThis.NoirSound();this.name=localStorage.getItem('trpg:name')||'';this.selected=null;this.tab='self';this.draft='';this.chatMode='say';this.overlay=null;this.feedTab='story';this.typing=new Map();this.typingSound=true;this.writer=setInterval(()=>this.advanceText(),30);this.root.addEventListener('click',e=>this.click(e));this.root.addEventListener('input',e=>{if(e.target.id==='draft')this.draftInput(e.target.value);if(e.target.id==='will')this.will=e.target.value;if(e.target.id==='press-headline'||e.target.id==='press-article'){this.pressDraft??={};this.pressDraft[e.target.id]=e.target.value;this.lastDraftInput=performance.now();}if(e.target.id==='reason'){this.trialReason=e.target.value;this.lastDraftInput=performance.now();}});this.root.addEventListener('change',e=>{if(e.target.id==='mode'){this.chatMode=e.target.value;this.render();}if(['guess-role','guess-team'].includes(e.target.id))this.guess();if(e.target.id==='accused')this.trialTarget=e.target.value;if(e.target.id==='press-photo'){this.pressDraft.photo=e.target.value;this.root.querySelector('[data-photo-preview]').innerHTML=this.photoView(this.now.view.me.photos.find(p=>p.id===e.target.value));}if(e.target.id.startsWith('offer-')){this.offerFacts??={};this.offerFacts[e.target.id.slice(6)]=e.target.value;}if(e.target.dataset.caseFact){this.trialFacts??=new Set();if(e.target.checked)this.trialFacts.add(e.target.dataset.caseFact);else this.trialFacts.delete(e.target.dataset.caseFact);}if(e.target.dataset.pickField&&this.actionPicker){this.actionPicker[e.target.dataset.pickField]=e.target.value;this.render();}});this.root.addEventListener('compositionstart',e=>{if(e.target.matches('textarea'))this.composing=true;});this.root.addEventListener('compositionend',e=>{if(e.target.matches('textarea')){this.composing=false;this.compositionEnded=performance.now();if(e.target.id==='draft')this.draftInput(e.target.value);else if(e.target.id==='reason')this.trialReason=e.target.value;else if(e.target.id==='will')this.will=e.target.value;if(e.target.id==='press-headline'||e.target.id==='press-article'){this.pressDraft??={};this.pressDraft[e.target.id]=e.target.value;this.lastDraftInput=performance.now();}this.deferRender();}});this.root.addEventListener('keydown',e=>{if(e.target.id==='draft'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!this.composing&&e.keyCode!==229&&performance.now()-(this.compositionEnded||0)>80){e.preventDefault();this.send();}});this.engine.bus.on('room',n=>{this.now=n;this.render();},this);this.engine.bus.on('room:gone',()=>{this.now=null;this.render();},this);this.root.addEventListener('pointerdown',()=>{this.sound.unlock();},{passive:true});this.root.addEventListener('keydown',()=>{this.sound.unlock();},{passive:true});this.engine.room.resume();this.render();this.clock=setInterval(()=>this.tick(),500);}
 destroy(){clearInterval(this.clock);clearInterval(this.writer);clearTimeout(this.inputRenderTimer);this.sound.destroy();this.root.remove();}
 el(id){return this.root.querySelector('#'+id);}
 // 이야기 글 속의 따옴표 대사를 "이름: 내용" 줄로 바꾼다. 첫 장면 원문은 그대로 둔다.
 dialogue(text){
  text=String(text??'');
  if(!text.includes('"')||text.startsWith('간밤 보안관이 얼굴을 가린'))return text;
  const players=(this.now?.view?.people||[]).map(p=>p.name).filter(Boolean);
  const alias={'시장':'해먼드','주인':'술집 주인','노조위원장':'도일'};
  const names=[...players,'해먼드','도일','간호사','광부','아이','주민','이웃','술집 주인','주인','시장','누군가'].sort((a,b)=>b.length-a.length);
  const esc=x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const re=new RegExp('('+names.map(esc).join('|')+')(이|가|은|는)?','gu');
  const pick=seg=>{let subj=null,any=null;for(const m of seg.matchAll(re)){any=m[1];if(m[2])subj=m[1];}const n=subj||any;return n?(alias[n]||n):null;};
  let out='',at=0,last=null;
  for(const m of text.matchAll(/"([^"]+)"/g)){
   const end=m.index+m[0].length,before=text.slice(at,m.index).trim();
   // 따옴표 바로 뒤에 글자가 붙으면("…"라고, "…"를 읽었다) 말이 아니라 인용이므로 그대로 둔다.
   if(/^[\p{L}\p{N}]/u.test(text.slice(end)))continue;
   let who=pick(before);
   if(!who){const after=(text.slice(end).match(/^[^."]*/)||[''])[0];who=pick(after)||(!before&&last)||null;}
   if(!who)continue; // 누가 한 말인지 글에서 알 수 없으면 바꾸지 않는다.
   last=who;out+=(before?before+'\n':'')+'⁣'+who+': '+m[1].trim()+'\n';at=end;
  }
  return (out+text.slice(at).trim()).trim();
 }
 // NPC가 한 말에서 겉따옴표를 떼고, 뒤에 붙은 지문은 괄호에 넣는다.
 speechText(e){const t=String(e.text??'').trim();if(!this.isNpcSpeech(e))return t;const m=t.match(/^"([^"]*)"\s*([\s\S]*)$/);return m?m[1]+(m[2].trim()?' ('+m[2].trim()+')':''):t;}
 isNpcSpeech(e){return !!e.npc||/ · NPC$/.test(String(e.name||''));}
 // dialogue()가 표시해 둔 화자 이름에 색을 입힌다. 플레이어와 NPC의 색이 다르다.
 saidMarkup(html){return html.replace(/⁣((?:<[^>]+>|[^<:\n])+?):/g,(m,who)=>'<b class="said '+(/term-player/.test(who)?'said-player':'said-npc')+'">'+who+':</b>').replace(/⁣/g,'');}
 personName(name,id){const me=this.now?.view?.me?.id;return `<button type="button" class="term term-player" data-do="person" data-id="${E(id)}" title="플레이어${id===me?' · 나':''} · 내가 아는 정보 보기">${E(name)}</button>`;}
 richText(text,fullText=text){
  const visible=String(text??''),full=String(fullText??'');
  // Only public roster names and authored vocabulary; no hidden state or inferred identities.
  const terms=new Map(),add=(word,kind,id)=>{if(word&&!terms.has(word))terms.set(word,{word,kind,id});};
  for(const p of this.now?.view?.people||[])add(p.name,'player',p.id);
  for(const word of ['해먼드','도일','리스','간호사','광부','시장','암거래 연락책','술집 연락책','연락책','관리인','보관인','종지기','전달인','정보 판매자'])add(word,'npc');
  for(const word of ['폭약','도화선','권총','탄약','붕대','단검','곤봉','치료제'])add(word,'item');
  for(const word of ['잘린 전화선','전화선','창고 근무표','근무표','출입 장부','외상 장부','장부','정산 사본','정산표','정산 기록','정비표','진료 기록','진료소 기록','출입 기록','수선표','수선 기록','피 묻은 외투','외투','영수증','인수증','거래 쪽지','거래 기록','수리 의뢰','종 기록','손수건 반납표','유리 파편','천 조각','열쇠','투표용지','봉투','교대 시계','기름 자국','약품 목록','회중시계','숙박부','체포장','관인','차용증','걸쇠','발자국','담보표','배급표','금고','승선 명단','운송표','인수증','계약서','무전 기록','협박장','고발 쪽지','정산함','가격표','보급 명단','원판','지도','택표','퓨즈','영수증','사진','봉인','인장','접수표'])add(word,'clue');
  if(!terms.size)return this.saidMarkup(E(visible));
  const escape=x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const pattern=new RegExp([...terms.keys()].sort((a,b)=>b.length-a.length).map(escape).join('|'),'gu');
  const letter=/[\p{L}\p{N}_]/u,ending=/^(?:님(?:은|는|이|가|을|를|께|에게|의)?|에게서(?:도|는|만)?|에게(?:도|는|만)?|한테(?:도|는|만)?|에서(?:도|는|만)?|으로(?:도|는|만)?|부터|까지|이라|이란|이라고|라고|이라는|라는|이|가|은|는|을|를|의|와|과|도|만|에|로|과는|와는|임|입니다|였다|입니다만)(?=$|[^\p{L}\p{N}_])/u;
  let html='',at=0;
  for(const m of full.matchAll(pattern)){
   const start=m.index,end=start+m[0].length;if(start>=visible.length)break;
   const before=start?full[start-1]:'',after=full.slice(end);
   if(before&&letter.test(before)||after&&letter.test(after[0])&&!ending.test(after))continue;
   html+=E(visible.slice(at,start));const t=terms.get(m[0]),part=visible.slice(start,Math.min(end,visible.length));
   if(t.kind==='player')html+=this.personName(part,t.id);
   else {const title={npc:'NPC · 마을의 보조 인물',item:'아이템 언급 · 소지 여부는 소지품에서 확인',clue:'단서·기록 언급 · 내용의 진실이 확정된 것은 아닙니다'}[t.kind];html+=`<span class="term term-${t.kind}" title="${title}">${E(part)}</span>`;}
   at=Math.min(end,visible.length);
  }
  return this.saidMarkup(html+E(visible.slice(at)));
 }
 toast(s){this.root.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=s;this.root.appendChild(el);setTimeout(()=>el.remove(),5000);}
 async call(fn){try{const r=await fn();if(r?.ok===false)this.toast(r.error);return r;}catch(e){this.toast('서버 연결을 확인해 주세요.');return null;}}
 draftInput(value){this.draft=value;this.lastDraftInput=performance.now();if(this.renderQueued)this.deferRender();}
 deferRender(){clearTimeout(this.inputRenderTimer);this.inputRenderTimer=setTimeout(()=>{if(this.composing){this.deferRender();return;}if(this.renderQueued){this.renderQueued=false;this.render();}},400);}
 render(){if(this.composing||performance.now()-(this.lastDraftInput??-1000)<350){this.renderQueued=true;this.deferRender();return;}const focus=document.activeElement?.id,sel=document.activeElement?.selectionStart;const oldScroll=this.el('story-scroll'),scroll=oldScroll?.scrollTop,atEnd=!oldScroll||oldScroll.scrollHeight-oldScroll.scrollTop-oldScroll.clientHeight<45;const n=this.now,v=n?.view;
 if(v){this.syncText(v);const stageKey=this.now.room+':'+v.epoch+':'+v.stage;if(this.displayStage!==stageKey){this.displayStage=stageKey;if(['opening','clash','result','trial','vote','summons','decision','consent'].includes(v.stage))this.feedTab='story';}}if(!n)this.root.innerHTML=this.home();else if(n.status==='lobby')this.root.innerHTML=this.lobby();else if(v)this.renderPlay(v);if(this.trialOpen&&(!v||v.epoch!==this.trialOpen.epoch||v.stage!=='plan'||v.ready))this.trialOpen=null;const trialNode=this.root.querySelector('[data-trial-request]');if(!this.trialOpen)trialNode?.remove();else if(!trialNode)this.root.insertAdjacentHTML('beforeend',this.trialDialog(v));if(this.pressOpen&&(!v||v.epoch!==this.pressOpen.epoch||v.stage!=='plan'||v.ready))this.pressOpen=null;const pressNode=this.root.querySelector('[data-press-editor]');if(!this.pressOpen)pressNode?.remove();else if(!pressNode)this.root.insertAdjacentHTML('beforeend',this.pressDialog(v));if(v?.consent&&v.stage==='consent'&&v.me.hp>0&&this.consentCollapsed!==v.consent.id)this.root.insertAdjacentHTML('beforeend',this.consentDialog(v));if(this.overlay)this.root.insertAdjacentHTML('beforeend',this.overlay);else if(this.actionPicker&&v){const picker=this.pickerView(v);if(picker)this.root.insertAdjacentHTML('beforeend',picker);}
 if(focus&&focus!=='draft'&&this.el(focus)){this.el(focus).focus();try{this.el(focus).setSelectionRange(sel,sel);}catch(e){}}
 const box=this.el('story-scroll');if(box)box.scrollTop=atEnd?box.scrollHeight:scroll;if(this.chatToBottom&&box){box.scrollTop=box.scrollHeight;this.chatToBottom=false;}this.tick();
 this.paintDamage(v);this.animateSlide();
 if(v){const key=v.epoch+':'+v.stage;if(this.lastStage!==key){this.lastStage=key;const cue=v.stage==='vote'?'verdict':v.stage==='trial'?'defense':v.stage==='end'?'end':v.turn===2?'night':'day';try{this.sound.update(cue,key);}catch(e){}}}
 }

 renderPlay(v){const oldCenter=this.root.querySelector('.center'),composer=this.root.querySelector('.composer');if(!oldCenter||!composer){this.root.innerHTML=this.play(v);return;}
 // Keep the focused textarea connected to the same document during room updates/IME input.
 const fresh=document.createElement('div');fresh.innerHTML=this.play(v);const nextCenter=fresh.querySelector('.center');for(const child of [...oldCenter.children])if(child!==composer)child.remove();let before=true;for(const child of [...nextCenter.children]){if(child.classList.contains('composer')){before=false;continue;}if(before)oldCenter.insertBefore(child,composer);else oldCenter.appendChild(child);}
 const mode=composer.querySelector('#mode'),send=composer.querySelector('[data-do=send]');if(mode.value!==this.chatMode)mode.value=this.chatMode;send.textContent=this.sending?'전송 중…':this.chatMode==='say'?'말하기':'의도 확인';send.disabled=!!this.sending;const field=composer.querySelector('#draft'),hint=this.chatMode==='say'?'같은 장소의 사람에게 말하세요.':'하고 싶은 행동을 적으세요. 실행 전에 의도를 확인합니다.';if(field.placeholder!==hint)field.placeholder=hint;
 for(const sel of ['header','.people','.self'])this.root.querySelector(sel)?.replaceWith(fresh.querySelector(sel));for(const child of [...this.root.children])if(!child.matches('header,.layout,[data-trial-request],[data-press-editor]'))child.remove();for(const child of [...fresh.children])if(!child.matches('header,.layout'))this.root.appendChild(child);
 }
 compositionDialog(v){return `<div class="overlay"><section class="role-composition" role="dialog" aria-modal="true" aria-labelledby="composition-title"><small>개인별 배정은 추리로 확인합니다</small><h2 id="composition-title">이번 판의 직업 구성</h2>${v.composition?v.composition.map(g=>`<div class="composition-group ${g.team}"><h3>${({mafia:'마피아',town:'시민',neutral:'중립'})[g.team]}</h3>${g.roles.length?g.roles.map(x=>`<p><span>${E(C.roles[x.role]?.name||x.role)}</span><b>${x.count}명</b></p>`).join(''):'<p class="muted">이번 판에는 없음</p>'}</div>`).join(''):'<p>이전 실행본의 판입니다. 수정된 서버의 새 판부터 실제 구성표가 제공됩니다.</p>'}<p class="muted">시작 직업은 진영별로 배정됩니다. 영입된 인물은 기존 직업을 유지하며, 영입 여부는 이 표에 공개되지 않습니다.</p><button data-do="close">닫기</button></section></div>`;}
 paintDamage(v){if(!v)return;const key=this.now.room+':'+this.now.round+':'+v.me.id,now=performance.now();if(this.hpKey!==key){this.hpKey=key;this.prevHp=v.me.hp;this.prevFeed=v.feed.at(-1)?.i||0;this.hpFx=null;}
 if(this.prevHp!==v.me.hp){const hit=v.feed.findLast(e=>e.i>this.prevFeed&&e.kind==='combat'&&e.target===v.me.id);this.hpFx={from:this.prevHp,to:v.me.hp,at:now,hit:!!hit,impact:hit?.impact||'blunt'};if(hit&&this.prevHp>v.me.hp)this.sound.impact(this.hpFx.impact);this.prevHp=v.me.hp;}this.prevFeed=v.feed.at(-1)?.i||this.prevFeed;
 const fx=this.hpFx;if(!fx)return;const age=now-fx.at;if(age<900){for(const bar of [this.root.querySelector('.self-card .healthbar i'),this.root.querySelector('.person[data-id="'+v.me.id+'"] .resident-hp i')].filter(Boolean)){const anim=bar.animate([{width:fx.from*10+'%'},{width:fx.to*10+'%'}],{duration:900,easing:'ease-out',fill:'both'});anim.currentTime=age;}}
 if(fx.hit&&fx.from>fx.to&&age<1600){const layer=document.createElement('div');layer.className='damage-vignette';layer.setAttribute('aria-hidden','true');layer.innerHTML='<i></i><i></i><i></i><span>−'+(fx.from-fx.to)+'</span>';this.root.appendChild(layer);const anim=layer.animate([{opacity:0},{opacity:.8,offset:.15},{opacity:.65,offset:.45},{opacity:0}],{duration:1600,fill:'both'});anim.currentTime=age;anim.onfinish=()=>layer.remove();}
 }
 home(){return `<div class="welcome"><div class="film-bg"></div><section class="title-card"><small>1947 · 고립된 광산 마을</small><h1>밤의 증언</h1><p class="subtitle">블랙 리지</p><div class="ruleline"></div><p>누군가는 숨기고, 누군가는 보았다.<br>외부의 법이 도착하기 전, 마을의 운명을 결정하십시오.</p><label>이름<input id="name" maxlength="20" placeholder="마을에서 부를 이름" value="${E(this.name)}"></label><div class="row"><label>참가 인원<select id="count"><option value="8">8명</option><option value="6">6명</option><option value="4">4명</option><option value="12">12명</option></select></label><button data-do="solo" class="gold">혼자 하기 · AI 자리 채우기</button></div><div class="row"><button data-do="create">방 만들기</button><input id="code" placeholder="방 이름" maxlength="6"><button data-do="join">들어가기</button></div><small>낮 2턴 · 밤 1턴 / 진행 시간 최대 50분 · 이야기 정지 제외 / 마피아·시민 전용 직업</small></section></div>`;}
 mast(){return `<header><b>밤의 증언 <span>블랙 리지</span></b><span class="room">방 ${E(this.now?.room||'')}</span><button data-do="sound">${this.sound.enabled?'음악 끄기':'음악 켜기'}</button><button data-do="leave">나가기</button></header>`;}
 lobby(){const n=this.now;return `${this.mast()}<section class="lobby"><small>마을 회관 · 개회 전</small><h1>주민들이 모이고 있습니다</h1><p>방 이름 <strong>${E(n.room)}</strong>을 다른 창에 입력하면 함께 참가할 수 있습니다.</p><div class="seat-grid">${n.seats.map(p=>`<article><b>${E(p.name)}</b><span>${p.bot?'컴퓨터 자리':p.on?'접속 중':'접속 끊김'}</span></article>`).join('')}</div>${n.host?'<div class="row"><button data-do="add">AI 자리 추가</button><button data-do="remove">AI 자리 줄이기</button><button class="gold" data-do="start">마을 이야기 시작</button></div>':'<p>방장의 시작을 기다립니다.</p>'}<p class="muted">작은 행동으로 준비하고, 큰 행동으로 이야기를 바꿉니다.<br>진행자는 각자가 실제로 보고 들은 정보만 전합니다.</p></section>`;}
 play(v){const me=v.me,pl=C.places[me.location];return `${this.mast()}<div class="layout"><aside class="people"><div class="aside-head"><small>주민 수첩</small><div class="people-tabs" role="tablist"><button role="tab" data-do="people-tab" data-tab="players" aria-selected="${this.peopleTab!=='npcs'}">플레이어 ${v.people.filter(p=>p.hp>0).length}/${v.people.length}</button><button role="tab" data-do="people-tab" data-tab="npcs" aria-selected="${this.peopleTab==='npcs'}">NPC</button></div></div><div class="people-list">${this.peopleTab==='npcs'?this.npcCards(v):[...v.people.filter(p=>p.here||p.id===me.id),...v.people.filter(p=>!p.here&&p.id!==me.id)].map(p=>this.personCard(p,me)).join('')}</div><button class="composition-open" data-do="composition">직업 구성</button></aside><section class="center"><div class="location-bar"><div><small>${E(v.time)}</small><h1>${E(v.locationName||pl.name)}</h1></div><div class="phase"><b>${v.stage==='hazard'&&!v.hazard?'행동 결과':stage[v.stage]}</b></div></div>${v.verdict?this.verdictView(v.verdict):`<div class="scene-image scene-${pl.photo} ${v.turn===2?'night':''}" role="img" aria-label="${pl.name}의 사진"><div class="scene-caption">${E(v.locationName||pl.name)}<span>${v.turn===2?'밤의 정적':'고립된 마을'}</span></div></div>`}<div class="environment"><small>환경 사실 · 내가 감지한 것</small>${v.environment.map(t=>`<p>${this.richText(t)}</p>`).join('')}</div><div class="story-title"><div class="feed-tabs" role="tablist" aria-label="기록 보기">${[['story','전체'],['speech','대화 목록'],['actions','행동 목록'],...(this.selected&&v.people.some(p=>p.id===this.selected)?[['person',v.people.find(p=>p.id===this.selected).name+' 정보']]:[])].map(([id,title])=>`<button role="tab" aria-selected="${this.feedTab===id}" data-do="feed-tab" data-tab="${id}">${title}${id==='speech'&&this.feedTab!=='speech'&&v.feed.some(e=>e.kind==='speech'&&e.i>(this.lastSpeechRead||0))?' · 새 대화':''}</button>`).join('')}</div><div class="reading-tools">${v.chapter?'<button data-do="archive">이전 기록</button>':''}</div></div><div class="story" id="story-scroll" tabindex="0" role="log" aria-label="내가 보고 들은 누적 이야기" aria-live="off">${this.feedTab==='person'?this.personInfo(v):this.feedHtml(v)}</div><div class="chat-clock"><span>${E(v.time)} · ${v.stage==='hazard'&&!v.hazard?'행동 결과':stage[v.stage]}</span><b id="chat-clock" role="timer"></b></div><div class="composer"><select id="mode"><option value="say" ${this.chatMode==='say'?'selected':''}>말하기</option><option value="action" ${this.chatMode==='action'?'selected':''}>행동하기</option></select><textarea id="draft" rows="2" maxlength="500" placeholder="${this.chatMode==='say'?'같은 장소의 사람에게 말하세요.':'하고 싶은 행동을 적으세요. 실행 전에 의도를 확인합니다.'}">${E(this.draft)}</textarea><button class="gold" data-do="send">${this.chatMode==='say'?'말하기':'의도 확인'}</button></div>${this.npcButtons(v)}${this.actionPanel(v)}</section><aside class="self"><div class="self-card"><small>내 인물</small><h2 class="player-label">${E(me.name)}</h2><div class="badges"><span>${C.roles[me.role].name}</span><span class="${me.team}">${me.team==='mafia'?'마피아 편':'시민 편'}</span></div><div class="healthbar"><i style="width:${me.hp*10}%"></i></div><p>체력 <b>${me.hp} / 10</b> ${me.bleeding?'<em>출혈 · 턴 끝 -1</em>':''}</p></div><nav>${[['self','능력'],['bag','소지품'],['notes','수첩'],['story','이어지는 사건'],['press','신문'],['rules','게임 정보'],['will','유언']].map(([id,t])=>`<button data-do="tab" data-tab="${id}" class="${this.tab===id?'active':''}">${t}</button>`).join('')}</nav><div class="side-content">${this.right(v)}</div><div class="time-budget"><small>외부 지원</small><b>6일째 아침 도착</b><span>진행 시간 · 읽기 제외 <span id="elapsed"></span> / 최대 50분</span><p>큰 행동 ${me.used.big?'사용':'1회'} · 작은 행동 ${me.used.small?'사용':'1회'}</p><small>${v.ai.mode==='on'?'구독 GPT 연결':'규칙 진행 모드'} · 응답 ${v.ai.answered}<br>규칙 대체 ${v.ai.fallback} · 대기 ${v.ai.pending}</small></div></aside></div>${v.result&&v.stage!=='decision'&&!this.dismissEnd?this.ending(v):''}`;}
 // 마을의 NPC. 누구인지만 알려 주고, 어디에 있는지와 무엇을 아는지는 알려 주지 않는다.
 npcCards(v){const here=new Map((v.story?.npcs||[]).map(n=>[n.name,n]));const cast=[['해먼드','블랙 리지의 시장'],['도일','광부 노조의 대표'],['간호사','진료소의 간호사'],['광부','광산에서 일하는 사람들'],['술집 주인','광부 술집의 주인'],['아이','주택가의 아이'],['주민','이름을 모르는 이웃들'],['리스','간밤에 숨진 보안관']];
  return cast.map(([name,who])=>{const n=here.get(name),gone=name==='리스'||n&&n.hp===0;return `<div class="person npc-card ${gone?'dead':''}"><span class="initial">${E(name.slice(0,1))}</span><span class="person-body"><span class="person-heading"><b class="npc-label">${E(name)}</b></span><span class="person-meta"><span class="condition">${E(who)}${n&&n.hp>0&&n.hp<10?(n.bleeding?' · 출혈':' · 부상'):''}</span><small>${n&&n.hp>0?'지금 여기':''}</small></span></span></div>`;}).join('');}
 personNotes(p,me){const v=this.now?.view,g=v?.me?.guesses?.[p.id]||{},facts=(v?.me?.known||[]).filter(k=>k.about===p.id).length,n=[];if(p.id!==me.id&&p.hp>0&&!p.here)n.push(p.lastSeen?'마지막 목격 · '+(C.places[p.lastSeen.place]?.short||C.places[p.lastSeen.place]?.name||''):'어디 있는지 모름');if(p.id!==me.id){if(g.role&&g.role!=='unknown'&&C.roles[g.role])n.push('내 추측 · '+C.roles[g.role].name);else if(g.team&&g.team!=='unknown')n.push('내 추측 · '+(g.team==='mafia'?'마피아 편':'시민 편'));}if(facts)n.push('기록 '+facts+'건');return n.length?`<span class="person-notes">${n.map(E).join(' · ')}</span>`:'';}
 personCard(p,me){const state=p.hp===0?'dead':p.hp<=2?'critical':p.hp<=5?'wounded':'healthy';return `<button class="person ${p.id===this.selected?'selected':''} ${state} ${p.here||p.id===me.id?'in-sight':'out-of-sight'}" data-do="person" data-id="${p.id}"><span class="initial">${E(p.name.slice(0,1))}</span><span class="person-body"><span class="person-heading"><b class="player-label">${E(p.name)}${p.id===me.id?' · 나':''}</b><span class="hp-number">${p.hp}<small>/10</small></span></span><span class="resident-hp" role="meter" aria-label="${E(p.name)} 체력" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${p.hp}"><i style="width:${Math.max(0,Math.min(10,p.hp))*10}%"></i></span></span></button>`;}
 actionName(type){return ({photograph:'사진 찍기',publish:'신문 만들기',scene:'현장에서 행동하기',buy:'물건 구매하기',evidence:'이 장소 조사하기',move:'이동하기',attack:'공격하기',give:'아이템 주기',investigate:'인물 조사',observe:'주변 보기',hide:'숨기',unhide:'모습 드러내기',bandage:'지혈하기',heal:'치료하기',jail:'구금하기',recruit:'영입 제안',persuade:'협조 요청하기',wait:'기다리기',share:'증언하기'})[type]||type;}
 pickerChoices(){return (this.options||[]).filter(a=>a.type===this.actionPicker?.type&&(!this.actionPicker.sceneKey||a.sceneKey===this.actionPicker.sceneKey)&&(!this.actionPicker.eventId||a.eventId===this.actionPicker.eventId&&a.pathIndex===this.actionPicker.pathIndex));}
 pickerView(v){const q=this.actionPicker;if(q.epoch!==v.epoch||q.stage!==v.stage||v.ready||v.me.hp<=0){this.actionPicker=null;return '';}
 const opts=this.pickerChoices();if(q.type==='scene'&&opts.length){q.sceneChoice=Math.max(0,Math.min(opts.length-1,Number(q.sceneChoice)||0));const a=opts[q.sceneChoice];return `<div class="overlay action-picker"><div role="dialog" aria-modal="true"><h2>${q.sceneKey==='forge'?'출입 기록 위조하기':E(a.label)}</h2><label>무엇을 합니까?<select data-pick-field="sceneChoice">${opts.map((o,i)=>`<option value="${i}" ${i===q.sceneChoice?'selected':''}>${E(o.label)}</option>`).join('')}</select></label><p>${E(a.hint||'')}</p><div class="picker-footer"><button data-do="cancel-picker">취소</button><button data-do="submit-picker" class="gold">${q.slot==='small'?'작은 행동으로 하기':'큰 행동으로 선택'}</button></div></div></div>`;}if(!opts.length){this.actionPicker=null;return '';}
 const fields=[];if(opts.some(a=>a.place))fields.push(['place','어디로 이동합니까?',x=>C.places[x]?.name||x]);if(opts.some(a=>a.target))fields.push(['target','누구에게 합니까?',x=>v.people.find(p=>p.id===x)?.name||'나']);if(opts.some(a=>a.weapon))fields.push(['weapon','어떤 무기를 씁니까?',x=>C.weapons[x]?.name||x]);if(opts.some(a=>a.request))fields.push(['request','무엇을 부탁합니까?',x=>x==='bandage'?'붕대 한 개':'알고 있는 기록 한 건의 증언']);
 let form='';for(const [key,label,name] of fields){const values=[...new Set(opts.map(a=>a[key]).filter(Boolean))];if(!values.includes(q[key]))q[key]=values[0];form+=`<label>${label}<select data-pick-field="${key}">${values.map(x=>`<option value="${E(x)}" ${q[key]===x?'selected':''}>${E(name(x))}</option>`).join('')}</select></label>`;}
 if(q.type==='photograph')form+='<p>큰 행동이 함께 처리되는 순간의 현장을 촬영합니다. 상대가 이동한다면 떠나기 직전의 모습이 남습니다. 보관한 사진은 아직 다른 사람에게 공개되지 않습니다.</p>';
 if(q.type==='attack')form+='<p class="muted">낮에는 같은 장소의 상대를 공격합니다. 밤의 집 습격은 찾아가기와 공격이 큰 행동1회입니다. 공격에 대응한 뒤 살아남은 사람이 이동합니다. 공개 공격은 주변에 보이는 사람1명당 -1, 최대 -3. 목격한 사람에게 공격 사실이 남습니다.</p>';
 if(q.type==='buy')form+=`<label>구매할 물건<select disabled><option>붕대 1개 · ${v.cfg.bandagePrice} / 소지금 ${v.me.money}</option></select></label><p class="muted">진료소에서 구매합니다. 지혈용이며 체력 회복 효과는 없습니다.</p>`;
 if(q.type==='give')form+=`<label>건넬 아이템<select disabled aria-label="건넬 아이템"><option>붕대 1개 · 보유 ${v.me.items.bandage}개</option></select></label><p class="muted">붕대는 이 메뉴에서 건넵니다. 수첩과 현장 물건은 ‘이어서 행동하기’에서 건넬 수 있습니다.</p>`;
 form+=`<p class="check-preview">${E(this.checkHint(q.type,v))}</p>`;
 const chosen=opts.find(a=>fields.every(([key])=>a[key]===q[key]));return `<div class="overlay action-picker"><div role="dialog" aria-modal="true" aria-labelledby="picker-title"><small>${q.slot==='small'?'작은 행동 · 나에게 즉시 결과':'큰 행동 · 결과는 모두 함께 처리'}</small><h2 id="picker-title">${E(this.actionName(q.type))}</h2>${form}<p class="picker-summary">${chosen?E(chosen.label):'가능한 대상을 선택하세요.'}</p><div class="picker-footer"><button data-do="cancel-picker">취소</button><button class="gold" data-do="submit-picker" ${chosen?'':'disabled'}>${q.slot==='small'?'이 행동 하기':'큰 행동으로 선택'}</button></div></div></div>`;
 }
 personInfo(v){const p=v.people.find(p=>p.id===this.selected);if(!p)return '<div class="person-detail muted">왼쪽에서 플레이어를 누르면 그 사람에 대해 내가 아는 것을 여기서 볼 수 있습니다.</div>';const g=v.me.guesses[p.id]||{};return `<div class="person-detail"><h3><span class="player-label">${E(p.name)}</span>에 대해 아는 것</h3><p class="person-vitals">체력 ${p.hp} / 10 · ${E(p.condition)}${p.bleeding?' · 출혈 중':''}${p.team==='mafia'&&v.me.team==='mafia'&&p.id!==v.me.id?' · 같은 편':''}${p.id===v.me.id?' · 나':''}</p><p class="known-location">위치: ${p.location?E(C.places[p.location]?.name):p.lastSeen?E(C.places[p.lastSeen.place]?.name):'아직 확인하지 못함'}${!p.location&&p.lastSeen?`<small>마지막 목격 · ${E(p.lastSeen.time)}<br>현재도 그곳에 있는지는 확인되지 않았습니다.</small>`:''}</p>${p.role?`<p>확인 가능한 직업: ${C.roles[p.role].name}</p>`:''}<label>예상 직업<select id="guess-role"><option value="unknown">모름</option>${Object.entries(C.roles).filter(([id])=>!v.composition||v.composition.some(g=>g.roles.some(x=>x.role===id))).map(([id,r])=>`<option value="${id}" ${g.role===id?'selected':''}>${r.name}</option>`).join('')}</select></label><label>예상 진영<select id="guess-team"><option value="unknown">모름</option><option value="town" ${g.team==='town'?'selected':''}>시민 편</option><option value="mafia" ${g.team==='mafia'?'selected':''}>마피아 편</option></select></label><small>내 추측이며 다른 사람에게 공개되지 않습니다.</small><div class="facts">${v.me.known.filter(k=>k.about===p.id).slice(-8).reverse().map(k=>`<article><small>${E(k.time)} · ${E(k.source)} · ${k.kind==='claim'?'주장':'확인 기록'}</small><p>${this.richText(k.text)}</p>${v.me.hp>0&&!(v.turn===2&&v.me.team==='town')?`<button data-do="share" data-id="${k.id}">대화로 전하기</button>`:''}</article>`).join('')||'<p>확인한 사실이 없습니다.</p>'}</div>${p.hp===0?`<button data-do="will" data-id="${p.id}">유언 읽기</button>`:''}<button class="person-back" data-do="feed-tab" data-tab="story">이야기로 돌아가기</button></div>`;}
 storyText(e){return this.dialogue(this.storyTextRaw(e));}
 storyTextRaw(e){
 const scenes={
 hall:'긴 의자 사이의 통로가 연단으로 이어집니다. 이곳에서 고발을 신청할 수 있지만, 지목만으로 재판이 열리지는 않습니다. 들은 주장과 직접 확인한 사실을 구분해 제시해야 합니다.',
 warehouse:'상자가 늘어선 좁은 통로 너머로 시야가 끊깁니다. 안쪽으로 들어가면 몸을 가리기는 쉽지만, 가까이에 누가 있는지도 놓치기 쉽습니다. 주변을 먼저 살필지, 모습을 감출지 선택할 수 있습니다.',
 tavern:'탁자와 바가 시야를 나눕니다. 같은 공간에 모습을 드러낸 사람과는 말을 나눌 수 있지만, 바 뒤편까지 보이는 것은 아닙니다. 들은 말은 증언이고, 확인한 흔적과는 다르게 기록됩니다.',
 clinic:'진찰등 아래로 처치대가 드러나 있습니다. 밝은 공간은 상처를 살피고 출혈을 막는 데 도움이 됩니다. 지혈은 피만 멎게 합니다. 이곳에서 치료하면 체력이 더 많이 돌아옵니다.',
 chapel:'긴 의자 사이로 촛불이 보이고, 목소리는 돌벽에 울립니다. 대화 상대가 같은 장소에 있어도 모습을 감췄다면 바로 알아볼 수 없습니다. 다가가기 전에 주변을 살펴볼 수 있습니다.',
 home:'창문 너머로 눈 쌓인 길이 보입니다. 이곳에 머무르거나 다른 장소로 이동할 수 있습니다. 다른 곳에서 무슨 일이 벌어졌는지는 소리를 듣거나 누군가의 증언을 얻기 전까지 알 수 없습니다.'
 };
 const place=Object.entries(C.places).find(([,p])=>e.text===p.text||(e.kind==='scene'&&e.text.includes(' · '+p.name+'. ')));
 if(place)return scenes[place[0]];
 if(e.text.startsWith('외부와 연결된 길'))return '마을 밖으로 이어지는 길이 끊겼습니다. 경찰과 판사가 도착하기 전까지, 마을 안의 고발과 판결은 이곳에 모인 주민들의 몫입니다.\n주민들은 회관에서 고발과 투표로 마피아를 가려내기로 했습니다. 이제 회관에 남아 이야기를 나누거나, 다른 장소로 가서 직접 확인할 수 있습니다.\n'+e.text.split('했습니다. ').slice(-1)[0];
 if(e.kind==='combat')return e.text;
 if(e.roll&&Number.isFinite(e.roll.damage)){const r=e.roll;return e.text+' '+(r.damage===0?'대응이 공격의 충격을 모두 줄여 이번에는 체력을 잃지 않았습니다.':r.reduction>0?'방어가 피해 일부를 줄였지만, 남은 충격으로 체력이 감소했습니다.':'공격 판정이 대응을 넘어 피해를 그대로 받았습니다.');}
 return e.text;
 }
 trialDialog(v){return `<div class="overlay" data-trial-request><div class="trial-request" role="dialog" aria-modal="true" aria-labelledby="trial-title"><small>마을 회관 · 큰 행동</small><h2 id="trial-title">재판 신청하기</h2><label>누구를 고발합니까?<select id="accused">${v.people.filter(p=>p.hp>0&&p.id!==v.me.id).map(p=>`<option value="${p.id}" ${this.trialTarget===p.id?'selected':''}>${E(p.name)}</option>`).join('')}</select></label><h3>내가 아는 기록에서 근거 선택</h3><p class="muted">최대 5개. 선택한 근거와 신청 이유는 모든 생존자에게 공고됩니다. 전해 들은 말은 확인된 사실과 구분됩니다.</p><div class="evidence-select">${v.me.known.length?v.me.known.map(k=>`<label class="fact-choice"><input type="checkbox" data-case-fact="${E(k.id)}" ${this.trialFacts?.has(k.id)?'checked':''}><span><small>${E(k.time)} · ${E(k.source)} · ${k.kind==='claim'?'전해 들은 주장':k.kind==='observed'?'직접 목격':'조사·문서 기록'}</small>${this.richText(k.text)}</span></label>`).join(''):'<p>현재 수첩에 확인한 기록이 없습니다. 이유만 적으면 근거 미첨부 주장으로 접수됩니다.</p>'}</div><label>신청 이유<textarea id="reason" maxlength="300" rows="3" placeholder="선택한 근거가 왜 이 사람과 관련되는지 적으세요.">${E(this.trialReason||'')}</textarea></label><p>접수 후 동의·반대를 받습니다. 생존자 ⅓ 동의 시 집계 직후 개정 · 하루 1회. 밤 신청은 다음 날 낮에 동의를 받습니다.</p><div class="picker-footer"><button data-do="trial-cancel">취소</button><button data-do="file" class="gold">재판 신청하기</button></div></div></div>`;}
 consentDialog(v){const c=v.consent;if(!c)return '';return `<div class="overlay consent-overlay"><section role="dialog" aria-modal="true" aria-labelledby="consent-title"><small>공식 재판 신청 · 범인의 유무를 정하는 최종 표결이 아닙니다</small><h2 id="consent-title">이 재판을 여는 데 동의합니까?</h2><p>신청자 <b>${this.personName(v.people.find(p=>p.id===c.by)?.name,c.by)}</b> → 재판 대상 <b>${this.personName(v.people.find(p=>p.id===c.target)?.name,c.target)}</b></p><p>${this.richText(c.reason)}</p><h3>신청자가 제출한 근거</h3>${c.evidence?.length?c.evidence.map(k=>`<blockquote><small>${E(k.time)} · ${E(k.source)}</small><p>${this.richText(k.text)}</p></blockquote>`).join(''):'<p class="muted">첨부한 기록 없음 · 신청자의 주장만 제출됨</p>'}<p class="consent-count">응답 ${c.responded} / ${c.total}명 · 동의 ${c.yes} · 반대 ${c.no}</p><p>필요 동의 ${c.needed}명. 모두 응답하거나 30초가 끝나면 집계합니다. 미응답은 별도로 집계합니다.</p>${c.mine===null?`<div class="picker-footer"><button data-do="consent-no" data-id="${c.id}">반대</button><button class="gold" data-do="consent-yes" data-id="${c.id}">동의</button></div>`:`<p><b>${c.mine?'동의':'반대'}로 응답했습니다.</b> 다른 사람의 응답을 기다립니다.</p>`}<button data-do="consent-hide" data-id="${c.id}">창 접기</button></section></div>`;}

 syncText(v){const key=this.now.room+':'+this.now.round+':'+this.now.me;if(this.textRoom!==key){this.ackedStory=null;this.textRoom=key;this.typing.clear();this.feedTab='story';this.textInitial=true;}
 const narrated=new Set(v.feed.flatMap(e=>e.narratedIds||[]));const feed=v.feed.filter(e=>e.kind!=='environment');for(const e of feed){if(this.typing.has(e.i))continue;const chars=Array.from(e.kind==='speech'?this.speechText(e):this.storyText(e));const past=e.i<(v.chapter?.from||0)||e.kind==='speech'||narrated.has(e.i)||this.textInitial&&v.elapsed>10;this.typing.set(e.i,{chars,n:past||e.who===v.me.id&&e.kind==='speech'?chars.length:0,next:0});}this.textInitial=false;
 const ids=new Set(feed.map(e=>e.i));for(const id of this.typing.keys())if(!ids.has(id))this.typing.delete(id);
 }
 feedHtml(v){if(['story','speech'].includes(this.feedTab))this.lastSpeechRead=Math.max(0,...v.feed.filter(e=>e.kind==='speech').map(e=>e.i));let events=v.feed.filter(e=>!v.chapter||e.i>=v.chapter.from);if(this.feedTab==='speech')events=events.filter(e=>e.kind==='speech');else if(this.feedTab==='actions')events=events.filter(e=>e.actionRecord===true&&e.kind!=='speech');else {const narrated=new Set(v.feed.flatMap(e=>e.narratedIds||[]));events=events.filter(e=>!narrated.has(e.i));const active=events.findIndex(e=>{const t=this.typing.get(e.i);return !['speech','environment'].includes(e.kind)&&t&&t.n<t.chars.length;});if(active>=0)events=events.filter((e,i)=>i<=active||['speech','environment'].includes(e.kind));}
 return events.length?events.map(e=>this.line(e,this.feedTab!=='story')).join(''):`<p class="empty-record">${this.feedTab==='speech'?'직접 들은 대화가 아직 없습니다.':'확인한 기록이 아직 없습니다.'}</p>`;
 }
 updateStory(){if(this.composing||this.feedTab==='person')return;const box=this.el('story-scroll');if(!box||!this.now?.view)return;const top=box.scrollTop,end=box.scrollHeight-top-box.clientHeight<45;box.innerHTML=this.feedHtml(this.now.view);box.scrollTop=end?box.scrollHeight:top;}
 line(e,history=false){const t=this.typing.get(e.i),complete=history||!t||t.n>=t.chars.length,text=history?(e.kind==='speech'?this.speechText(e):this.storyText(e)):t?t.chars.slice(0,t.n).join(''):this.storyText(e);const where=e.place?` · ${C.places[e.place]?.name||''}`:'';
 if(e.kind==='speech')return `<div class="speech ${e.dead?'dead-chat':''}"><small>${E(e.time+where)} · 직접 들은 대화</small><p><span class="speaker ${this.isNpcSpeech(e)?'said-npc':'said-player'}">${this.now?.view?.people?.some(p=>p.id===e.who)?this.personName(e.name,e.who):this.richText(String(e.name||'').replace(/ · NPC$/,''))}${e.dead?' · 사망자':''}:</span> ${this.richText(text)}</p></div>`;
 return `<article class="line ${E(e.kind)} ${!complete?'is-typing':''}" data-story-id="${e.i}"><small>${E(e.time+where)} · ${e.kind==='confrontation'?'눈앞의 대결 상황':e.kind==='combat'?'대결 결과':e.kind==='gm'?(e.generated?'진행자':'규칙 서술'):e.kind==='scene'?'주변 상황':e.kind==='preparation'?'나의 준비 결과':e.kind==='death'?'목격한 사망':e.kind==='notice'?'공식 공고':e.kind==='environment'?'감지한 주변 상황':e.kind==='check'?'행동의 결과':'진행자'}</small><p class="typed-text" data-type-id="${e.i}">${this.richText(text,this.storyText(e))}</p><span class="typing-caption" ${complete?'hidden':''}>진행자가 전하는 중…</span><div class="after-story" ${complete?'':'hidden'}>${e.roll?`<details><summary>판정 내역</summary>${this.roll(e.roll)}${e.roll.before!==undefined?`<br>체력 ${e.roll.before} → ${e.roll.after}`:''}</details>`:''}${e.newspaper?`<button data-do="newspaper" data-id="${e.newspaper}">신문 펼치기</button>`:''}${e.photo?`<button data-do="photo" data-id="${e.photo}">찍은 사진 보기</button>`:''}${e.kind==='death'?`<button data-do="will" data-id="${e.who}">유언 읽기</button>`:''}</div></article>`;
 }
 acknowledgeStory(){const v=this.now?.view;if(!v||v.readingStep!=='text'||v.ai.pending)return;const entries=v.feed.filter(e=>!['speech','environment'].includes(e.kind));if(entries.some(e=>{const t=this.typing.get(e.i);return t&&t.n<t.chars.length;}))return;const last=entries.at(-1)?.i||0,token=this.textRoom+':'+last;if(this.ackedStory===token)return;this.ackedStory=token;this.engine.room.act({type:'text-shown',last}).then(r=>{if(r?.ok===false)this.ackedStory=null;}).catch(()=>{this.ackedStory=null;});}
 advanceText(){if(this.composing)return;if(!this.now?.view||document.hidden||performance.now()<(this.nextStoryAt||0))return;const active=[...this.typing].find(([,t])=>t.n<t.chars.length);if(!active)return;const [id,t]=active,now=performance.now();if(this.feedTab==='story'&&!this.root.querySelector(`[data-type-id="${id}"]`)&&this.now.view.feed.find(e=>e.i===id)?.kind!=='speech'){const box=this.el('story-scroll');if(box)this.updateStory();return;}if(now<t.next)return;const ch=t.chars[t.n++];t.next=now+(/[.!?。]/.test(ch)?160:/[,，]/.test(ch)?75:25);const span=this.root.querySelector(`[data-type-id="${id}"]`);if(span&&this.feedTab==='story'){const box=this.el('story-scroll'),follow=box&&box.scrollHeight-box.scrollTop-box.clientHeight<45;span.innerHTML=this.richText(t.chars.slice(0,t.n).join(''),t.chars.join(''));if(this.typingSound&&/[^\s.,!?]/.test(ch))this.sound.typeClick();if(follow)box.scrollTop=box.scrollHeight;}
 if(t.n===t.chars.length){this.nextStoryAt=now+900;if(this.feedTab==='story'){const article=span?.closest('article');article?.classList.remove('is-typing');const caption=article?.querySelector('.typing-caption');if(caption)caption.hidden=true;const after=article?.querySelector('.after-story');if(after)after.hidden=false;setTimeout(()=>{if(this.now?.view&&this.feedTab==='story'){const box=this.el('story-scroll');if(box)this.updateStory();}},900);}}
 }
 revealText(){const entry=[...this.typing].find(([,t])=>t.n<t.chars.length);if(entry){entry[1].n=entry[1].chars.length;this.render();}}


 checkHint(type,v){return ({observe:'관찰 판정: d10 + 관찰 + 시야. 실제로 숨어 있는 상대의 은신과 비교합니다. 고정 난이도는 없으며 상대 은신 합계를 초과하면 발견합니다. 상대 수와 수치는 비공개입니다. 주변 보기는 공격 보정을 주지 않습니다.',evidence:'이 장소에 남은 단서와 흔적을 살핍니다(d10 + 관찰 ≥ 12). 알아낸 것은 수첩에 남고, 재판을 신청할 때 근거로 낼 수 있습니다. 살필 것이 없으면 작은 행동이 쓰이지 않습니다.',investigate:'인물 흔적: d10 + 관찰 + 시야 ≥ 16. 실패는 무죄 판정이 아닙니다.',hide:'숨기: d10 + 민첩 + 엄폐·밝기·밤 ≥ 12. 숨는 모습을 본 사람에게는 계속 보입니다.',bandage:'지혈: d10 + 치료 + 환경 ≥ '+v.cfg.medicalDifficulty+'. 붕대 사용: 두 주사위 중 높은 값 / 없음: 낮은 값. 체력 회복 없음.',recruit:'익명 쪽지로 합류를 제안합니다. 상대가 직접 수락해야 진영이 바뀌며, 수락하기 전에는 보낸 사람의 이름을 알 수 없습니다.',jail:'구금: 전투 판정 대 상대 민첩 판정. 동률이면 구금하지 못합니다.',move:'이동 조건을 확인해 처리합니다. 이동 자체에는 주사위를 굴리지 않습니다.',buy:'소지금과 장소 조건을 확인합니다. 구매에는 주사위를 굴리지 않습니다.',give:'소지품과 같은 장소 여부를 확인해 큰 행동으로 전달합니다.'})[type]||'';}
 roll(r){if(r.kind==='opposed')return `<b>시도 ${r.actor.total} : 대응 ${r.opponent.total} · ${r.success?'성공':r.tie?'동률 · 현상 유지':'실패'}</b><br>${this.roll(r.actor)}<hr>${this.roll(r.opponent)}`;
 if(r.kind==='check')return `<div class="check-breakdown"><b>${E(r.label||C.stats[r.statKey]+' 판정')} ${r.success===null?'':r.success?'· 성공':'· 실패'}</b><br>d10 ${r.rolls.length>1?'['+r.rolls.join(', ')+'] 중 '+(r.edge>0?'높은':'낮은')+' 값 ':''}(${r.roll}) + ${E(C.stats[r.statKey])} ${r.stat} + 환경 ${r.env} = <strong>${r.total}</strong>${r.difficulty!==null?' / 목표 난이도 '+r.difficulty+' 이상이면 성공':''}<br>${r.terms.length?r.terms.map(t=>E(t.label)+' '+(t.value>0?'+':'')+t.value).join(' · '):'별도 환경 보정 없음'}${r.edgeReason?'<br>'+E(r.edgeReason):''}${r.hiddenComparison?'<br><b>비교 기준: 내 합계 &gt; 상대 은신 합계</b><br>고정 난이도가 없는 비교 판정입니다. 상대의 수·은신 수치는 비공개이며, 새 발견이 없다고 주변에 아무도 없다는 뜻은 아닙니다.':''}</div>`;
 if(r.damage!==undefined&&r.attack===undefined)return `피해 ${r.damage}. 공격자의 세부 판정은 공개되지 않습니다.`;return r.attack!==undefined?`공격 d10(${r.attackRoll}) + 전투 ${r.attackStat} + 환경 ${r.env} = ${r.attack}<br>대응 d10(${r.defenseRoll}) + ${r.defenseType==='block'?'전투':'민첩'} ${r.defenseStat} + 환경 ${r.defEnv} = ${r.defense}<br>피해 ${r.base?r.base+' + ':''}d${r.die}(${r.raw}) + 전투 보정 ${r.bonus} − 대응 감소 ${r.reduction}${r.minimumDamage?' · 권총 명중 최소 '+r.minimumDamage+' 적용':''} → ${r.damage}<br>${E(r.envReason)} · ${E(r.defReason)}`:`합계 ${r.total} / 난이도 ${r.difficulty}`;}
 slot(v){const key=this.now.room+':'+this.now.round+':'+v.epoch;if(this.actionEpoch!==key){this.actionEpoch=key;this.actionSlot=v.me.used.small?'big':'small';this.smallWasUsed=v.me.used.small;this.slide=null;}else if(v.me.used.small&&!this.smallWasUsed){this.setSlot('big',false);this.smallWasUsed=true;}return this.actionSlot||'small';}
 setSlot(slot,draw=true){if(slot!==this.actionSlot){this.slide={from:this.actionSlot||'small',to:slot,at:performance.now()};this.actionSlot=slot;}if(draw)this.render();}
 animateSlide(){const track=this.root.querySelector('.action-track');if(!track||!this.slide)return;const passed=performance.now()-this.slide.at;if(passed>=360)return;const a=track.animate([{transform:this.slide.from==='big'?'translateY(-50%)':'translateY(0)'},{transform:this.slide.to==='big'?'translateY(-50%)':'translateY(0)'}],{duration:360,easing:'cubic-bezier(.22,.75,.25,1)',fill:'both'});a.currentTime=passed;}
 actionDeck(v,proposal=''){const me=v.me,slot=this.slot(v),state={players:[me,...v.people.filter(p=>p.id!==me.id).map(p=>({...p,hidden:!p.here}))],turn:v.turn,stage:v.stage,epoch:v.epoch,day:v.day,cfg:v.cfg,trialDay:v.trialDay};this.optionsBySlot={small:[...C.choices(state,me.id,'small').filter(a=>a.type!=='wait'),...(v.sceneSmallChoices||[])],big:[...C.choices(state,me.id,'big'),...(v.sceneChoices||[])]};this.options=this.optionsBySlot[slot];
 return `<div class="action-deck ${slot==='big'?'show-big':''}"><button class="slot-arrow fixed-arrow" data-do="switch-slot" data-slot="${slot==='small'?'big':'small'}" aria-label="${slot==='small'?'큰 행동으로 아래로 넘기기':'작은 행동으로 위로 넘기기'}"><span aria-hidden="true">${slot==='small'?'↓':'↑'}</span> ${slot==='small'?'큰 행동':'작은 행동'}</button><div class="action-track">${['small','big'].map(size=>{const used=me.used[size]||(size==='small'&&!!v.plans),opts=this.optionsBySlot[size],disabled=used||v.ready||v.turn===2&&me.team==='town';return `<section class="action-page action-slot slot-${size}" aria-hidden="${size!==slot}" ${size!==slot?'inert':''}><div class="slot-title"><b>${size==='small'?'작은 행동 · 나의 준비':'큰 행동 · 함께 처리'}</b><span>${used?0:1}/1</span></div>${v.turn===2&&me.team==='town'?'<p class="slot-hint">시민 편은 밤에 행동하지 않습니다.</p>':`<div class="choice-row">${[...new Set(opts.filter(a=>a.type!=='scene').map(a=>a.type))].map(type=>`<button data-do="action-group" data-slot="${size}" data-type="${type}" ${disabled?'disabled':''}>${E(this.actionName(type))}</button>`).join('')}${opts.filter(a=>a.type==='scene').filter((a,i,all)=>!['forge','incident','story-action'].includes(a.sceneKey)||all.findIndex(x=>x.sceneKey===a.sceneKey)===i).map(a=>`<button data-do="scene-choice" data-index="${opts.indexOf(a)}" data-slot="${size}" ${disabled?'disabled':''}>${E(({forge:'출입 기록 위조하기',incident:'현장의 일', 'story-action':'이어서 행동하기'})[a.sceneKey]||a.label)}</button>`).join('')}${size==='big'&&me.location==='hall'&&!me.used.big&&me.filedDay!==v.day+(v.turn===2?1:0)&&v.trialDay!==v.day+(v.turn===2?1:0)?`<button data-do="trial-open" ${disabled?'disabled':''}>재판 신청하기</button>`:''}</div>`}${used?'<p class="slot-hint">이번 턴에 이미 사용했습니다.</p>':''}${size==='big'&&v.plans?`<p class="chosen">선택: ${E(this.describe(v.plans,v))}</p>`:''}${size==='big'?'<p class="slot-hint">화면 이동은 횟수를 쓰지 않습니다. 큰 행동을 제출하면 남은 작은 행동은 생략합니다.</p>':''}</section>`;}).join('')}</div></div>${proposal}`;}
 sceneGuide(v){const g=v.sceneGuide;if(!g||v.me.hp<=0||!['plan','small'].includes(v.stage))return '';return `<section class="scene-guide" aria-label="이어지는 사건" title="${E(g.title)}"><div class="scene-buttons">${g.options.map((o,i)=>`<button data-do="scene-next" data-index="${i}" ${v.ready||v.plans||v.me.used[o.slot]||v.turn===2&&v.me.team==='town'?'disabled':''}>${E(o.label)} <small>· ${o.slot==='small'?'작은 행동':'큰 행동'}</small></button>`).join('')}${g.done?'<button data-do="tab" data-tab="notes">확인한 단서로 대화하기 · 수첩</button>':''}</div></section>`;}
 actionPanel(v){const me=v.me;if(v.result)return '';let html='';if(v.stage==='hazard'&&me.hp>0)html=v.hazard?`<p>${E(v.hazard.text)}</p><button data-do="hazard" data-choice="escape" ${v.hazard.choice?'disabled':''}>갱도 밖으로 대피</button><button data-do="hazard" data-choice="extinguish" ${v.hazard.choice||v.hazard.attempted?'disabled':''}>도화선 끄기 · 민첩 난이도 12</button>`:'<p>같은 시간대의 행동 결과를 기다립니다. 다른 장소의 상황은 직접 확인하기 전에는 알 수 없습니다.</p>';else if(me.hp<=0)html='<p>사망했습니다. 유언을 다시 읽거나 사망자끼리 대화할 수 있습니다.</p>';else if(['small','plan'].includes(v.stage)){html=this.actionDeck(v);
 }else if(v.stage==='gathering'){html='<p>처음 40초는 모두 회관에서 이야기합니다. 받은 쪽지를 꺼내 보이거나, 다른 주민에게 궁금한 것을 물어보세요. 이동과 행동은 이 시간이 끝난 뒤 시작합니다.</p>';}else if(v.stage==='consent'){const c=v.consent;html=`<h3>재판 개정 동의</h3><p>응답 ${c?.responded||0} / ${c?.total||0}명 · 동의 ${c?.yes||0} · 반대 ${c?.no||0}</p><button data-do="consent-show">신청 이유·근거와 동의 창 보기</button>`;}else if(v.stage==='react'){const cover=C.places[me.location].cover;html=v.threats.length?`<section class="combat-choice"><h3>공격이 다가옵니다 · 대응 선택</h3><p>${v.threats.map(t=>E(t.from)+'의 '+E(t.weapon)+' 공격').join(' / ')}</p><p>피하기: d10 + 민첩 ${me.stats.agility} + 엄폐 ${cover}<br>막기: d10 + 전투 ${me.stats.fight}</p><button data-do="defend" data-defense="dodge" aria-pressed="${v.reaction==='dodge'}">${v.reaction==='dodge'?'✓ ':''}몸을 피한다</button><button data-do="defend" data-defense="block" aria-pressed="${v.reaction==='block'}">${v.reaction==='block'?'✓ ':''}맞서 막는다</button><p class="reaction-status">${v.reaction?'선택한 대응: '+(v.reaction==='block'?'막기':'피하기')+' · 아래 버튼으로 확정':'아직 선택하지 않았습니다. 시간이 끝나면 기본 피하기로 판정합니다.'}</p><small>대응이 공격보다 높으면 피해6 감소, 동점 또는 2 낮으면 피해3 감소. 최종 피해는0 미만이 되지 않습니다. 권총은 완전히 피하지 못해 명중하면 최소5 피해입니다.</small></section>`:'<p>다른 주민이 공격에 대응하고 있습니다. 당사자의 선택이 끝날 때까지 기다립니다.</p>';}else if(v.stage==='trial'||v.stage==='vote')html=`<h3>${E(v.people.find(p=>p.id===v.trial.target)?.name)}의 재판</h3><p>${this.richText(v.trial.reason)}</p><button data-do="trial-evidence">재판 근거 보기 · ${v.trial.evidence?.length||0}건</button>${v.stage==='vote'&&me.id!==v.trial.target&&me.hp>0?'<button data-do="vote" data-vote="guilty">유죄</button><button data-do="vote" data-vote="innocent">무죄</button><button data-do="vote" data-vote="abstain">기권</button>':`<p>${v.stage==='trial'?'재판 대화 · 2분. 서로 질문하고 증언을 확인합니다.':'최종 변론과 표결 · 1분. 마지막 말을 전할 수 있습니다.'}</p>`}${v.trial.vote?`<p>내 표: ${E(v.trial.vote)}</p>`:''}`;else if(v.stage==='settle')html='<p>모두의 행동 판정은 끝났습니다. 각자 확인한 사실로 결과 이야기를 정리하고 있습니다.</p>';else html='<p>이야기가 모두 나온 뒤 10초 동안 읽을 시간을 드립니다. 그동안 게임 진행 시간은 멈춥니다.</p>';
 const proposal=me.proposal;if(me.interpreting)html+='<p>행동의 의도를 확인하고 있습니다…</p>';else if(proposal)html+=`<div class="proposal"><b>입력한 행동의 해석</b><p>${this.richText(proposal.explanation)}</p>${!proposal.invalid?`<button data-do="confirm" class="gold">${E(this.describe(proposal.proposal,v))} · 실행 의도로 제출</button>`:'<p>이 행동은 지금 실행할 수 없습니다. 다른 의도를 입력해 주세요.</p>'}</div>`;
 return `<div class="actions"><div class="action-progress">${v.progress?(v.progress.private?E(v.progress.label):`${E(v.progress.label)} <b>${v.progress.done} / ${v.progress.total}명</b>`):'이전 서버 · 새 실행본에서 인원 표시'}${this.sceneGuide(v)}</div>${html}<button class="ready gold" data-do="ready" ${['settle','consent','gathering','trial','vote','hazard'].includes(v.stage)||v.ready||v.readingStep&&v.readingStep!=='read'||v.stage==='react'&&(!v.threats.length||!v.reaction)?'disabled':''}>${v.stage==='trial'?'재판 대화 2분 · 시간이 끝나면 최종 변론':v.stage==='vote'?'최종 변론·표결 1분 · 시간이 끝나면 판결':v.stage==='gathering'?'대화 시간이 끝나면 행동 시작':v.stage==='hazard'?'긴급 대응 시간이 끝나면 결과 표시':v.stage==='settle'?'결과 이야기 준비 중':v.readingStep==='text'?'이야기를 전하는 중':v.readingStep==='hold'?'10초간 읽기 여유':v.ready?'다른 주민을 기다립니다':['opening','clash','result','summons','decision'].includes(v.stage)?'읽었습니다 · 다음으로':v.stage==='react'?'대응 확정':'선택 마치기 / 다음으로'}</button></div>`;
 }
 describe(a,v){return a.label||({move:`${C.places[a.place]?.name}로 이동`,attack:`${v.people.find(p=>p.id===a.target)?.name} 공격`,photograph:'사진 찍기',publish:'신문 만들기',scene:'현장에서 행동하기',file:'재판 신청',hide:'숨기',observe:'주변 보기',bandage:'지혈',heal:'치료',wait:'기다리기',attempt:'시도',recruit:'합류 제안',persuade:'협조 요청',buy:'붕대 구매',evidence:'이 장소 조사',give:'붕대 전달',investigate:'흔적 조사',share:'증언 공개',unhide:'몸 드러내기',jail:'구금'})[a.type]||a.type;}
 right(v){const p=v.me;if(this.tab==='story')return this.storyShelf(v);if(this.tab==='notes')return `<h3>내가 아는 기록</h3><div class="facts">${p.known.map(k=>`<article><small>${E(k.time)} · ${E(k.source)} · ${k.kind==='claim'?'전해 들은 주장':'확인한 기록'}</small><p>${this.richText(k.text)}</p>${p.hp>0&&!(v.turn===2&&p.team==='town')?`<button data-do="share" data-id="${E(k.id)}">대화로 전하기</button>`:''}</article>`).join('')}</div>`;if(this.tab==='press')return this.pressShelf(v);if(this.tab==='bag')return `<h3>소지품</h3><p>소지금 <b>${p.money??0}</b></p>${Object.entries(p.items).map(([id,n])=>`<div class="item"><span>${C.weapons[id]?.name||({dynamite:'폭약',bandage:'붕대',medicine:'치료제',ammo:'탄약',camera:'사진기',notebook:'리스의 수첩'})[id]||id}</span><b>${n}</b></div>`).join('')}<p class="muted">지혈은 체력을 회복하지 않습니다. 치료는 누구나 할 수 있습니다. 의사는 치료제를, 다른 사람은 붕대를 씁니다.</p>`;
 if(this.tab==='will')return `<h3>남길 유언</h3><textarea id="will" maxlength="500" rows="8">${E(this.will??p.will)}</textarea><button data-do="save-will">유언 저장</button><p class="muted">살아 있을 때는 나에게만 보입니다.</p>`;
 if(this.tab==='rules')return `<h3>마을의 규칙</h3><p>첫 도입 뒤 회관 대화 40초, 이후 낮 1 → 낮 2 → 밤. 공통60초 안에 작은 준비 행동 1회 뒤 큰 행동 1회. 작은 행동을 생략해도 시간은 초기화되지 않습니다. 모두 함께 다음 시간으로 넘어갑니다.</p><p>작은 행동: 주변 보기·숨기·증거 조사·붕대 구매·자기 지혈. 즉시 나만 결과를 봅니다. 큰 행동: 이동·공격·타인 지혈·물건 전달·치료·구금·고발·영입. 화살표로 화면을 오가도 시간과 행동권은 소모되지 않습니다. 말하기는 무료입니다.</p><p>판정: d10 + 이 게임의 능력치 + 해당 환경. 현장 조사 난이도12, 인물 흔적16. 주민 영입은 익명 쪽지와 상대의 수락으로 처리합니다. 증언이나 물건을 부탁하는 말은 일반 대화입니다. 성공해도 없는 증거를 만들거나 상대 선택을 강제하지 않습니다. 은신은 민첩, 발견은 관찰로 비교합니다.</p><p>대결: d10 + 능력 + 환경. 공개 공격은 주변에 보이는 제삼자1명당 -1(최대-3). 상대에게 들키지 않은 기습은 +2이며, 발견되면 기습 보너스 없음. 공격하려고 모습을 드러내면 현장의 사람에게 정체가 드러납니다. 숨기는 위장이나 신분 은폐가 아닙니다. 대결 후 생존자가 이동합니다. 피해: 무기 주사위 + 전투 보정(최대4). 공격−대응이 음수면 6, 0~2면 3 피해 감소. 권총은 완전히 빗나간 경우를 제외하면 최소5 피해(체력5 이하 중상). 밤에 집으로 가서 공격하는 것은 큰 행동1회입니다.</p><p>폭발은 실제 폭약 설치 후 점화해야 일어납니다. 점화 장면 뒤 15초 동안 대피하거나 도화선을 끌 수 있습니다. 현장에 남아 폭발을 직격으로 맞으면 체력과 관계없이 사망합니다. 폭발 피해를 주사위로 절반으로 줄이지 않습니다.</p><p>체력 1~2는 출혈. 처치하지 않으면 낮·밤 턴 끝 -1, 0이면 사망. 지혈 난이도11. 붕대는 두 d10 중 높은 값, 임시 처치는 낮은 값. 치료는 기본 체력1 회복, 의사가 하면 +2, 진료소에서 하면 +1. 의사는 치료제, 다른 사람은 붕대를 1개 씁니다. 이 수치는 첫 설계안입니다.</p><p>고발: 회관에서 하루1회. 신청을 공고하고 동의·반대를 받습니다. 생존자⅓ 동의 시 집계 직후 하루1건 재판. 접수 순서대로 찬반을 확인합니다. 유죄가 무죄보다 많으면 처형. 모두 회관으로 이동합니다. 재판 도입 뒤 대화 2분, 최종 변론·표결 1분. 이전 이야기는 별도 기록으로 보관합니다.</p><p>마피아 편이 생존자 절반 이상이면 장악. 도일이 노조를 넘겼으면 마피아 편을 한 명 더 셉니다. 협상은 상대 수락 필요. 6일째 아침 또는50분에 지원이 도착하면 시민 승리(초안).</p><p>현장 NPC는 플레이어 인원과 표결에 들어가지 않습니다. NPC의 부상·출혈과 치료도 같은 규칙을 따릅니다. 진료소의 한정된 붕대는 구입·기부로 수량이 바뀝니다. 수첩이나 현장 물건을 건넸다고 이미 알고 있던 사실까지 지워지지는 않습니다.</p><h3>오늘의 재판 신청</h3>${this.cases(v)}<p>AI 한도: 구독 연결 90회·내부환산200원. 한도/실패 때 규칙 행동과 확정 사실 서술로 이어집니다. 환산액은 청구액이 아닙니다.</p>`;
 return `<h3>${C.roles[p.role].name}</h3><p>${C.roles[p.role].desc}</p>${Object.entries(C.stats).map(([id,name])=>`<div class="stat"><span>${name}</span><div><i style="width:${p.stats[id]*10}%"></i></div><b>${p.stats[id]}</b></div>`).join('')}<p class="muted">능력 최대10 · 시작 직업은 진영별 배정<br>${p.team==='mafia'?'밤에도 행동할 수 있습니다.':'밤에는 행동하지 않습니다.'}</p>${v.offers.filter(o=>o.kind!=='help').map(o=>`<div class="offer"><b>${o.anonymous?'이름 없는 쪽지':E(v.people.find(p=>p.id===o.from)?.name)+'의 영입 제안'}</b><p>${E(o.terms)}</p>${o.amount?`<p>동봉된 돈 · ${o.amount} / 수락하면 받습니다.</p>`:''}${o.kind==='help'&&o.request==='testimony'?`<label>공유할 기록<select id="offer-${o.id}"><option value="">직접 고르기</option>${p.known.map(k=>`<option value="${E(k.id)}" ${this.offerFacts?.[o.id]===k.id?'selected':''}>${this.richText(k.text)}</option>`).join('')}</select></label>`:''}<button data-do="accept" data-id="${o.id}">${o.kind==='help'?(o.request==='bandage'?'붕대 하나 건네기':'고른 기록 증언하기'):'마피아 편 합류'}</button><button data-do="reject" data-id="${o.id}">거절</button></div>`).join('')}`;
 }
 cases(v){const needed=Math.ceil(v.people.filter(p=>p.hp>0).length/3),pending=v.plans?.type==='file'?`<article class="case pending"><b>재판 신청 접수 예정</b><p>${E(v.people.find(p=>p.id===v.plans.target)?.name)} · ${E(v.plans.reason)}</p><small>큰 행동 종료 뒤 찬반 창으로 알려 드립니다.</small></article>`:'';return pending+v.cases.map(c=>{const n=c.support.filter(id=>v.people.find(p=>p.id===id)?.hp>0).length,ended=c.closed||c.day<v.day;return `<article class="case"><b>${this.personName(v.people.find(p=>p.id===c.target)?.name,c.target)} · ${E(c.status||(ended?'종료':'찬반 집계 대기'))}</b><p>${this.richText(c.reason)}</p><small>동의 ${n} / 필요 ${needed} · ${c.day}일째 접수</small>${v.stage==='consent'&&v.consent?.id===c.id?'<p>찬반 선택은 화면의 개정 동의 창에서 합니다.</p>':''}</article>`;}).join('')||(pending||'<p class="muted">접수된 신청이 없습니다.</p>');}
 ending(v){return `<section class="ending"><small>마을의 기록</small><h1>${v.result.team==='mafia'?'마피아의 장악':v.result.team==='town'?'시민의 생존':'텅 빈 마을'}</h1><p>${E(v.result.text)}</p><p>경과 ${Math.floor(v.result.seconds/60)}분 ${v.result.seconds%60}초 · AI 응답 ${v.ai.answered} · 규칙 대체 ${v.ai.fallback}</p><div>${v.people.map(p=>`<p>${E(p.name)} · ${C.roles[p.role].name} · ${p.team==='mafia'?'마피아':'시민'} · ${p.condition} ${p.hp===0?`<button data-do="will" data-id="${p.id}">유언 읽기</button>`:''}</p>`).join('')}</div><button data-do="again">새 판 준비</button><button data-do="dismiss-end">기록 살펴보기</button></section>`;}
 async guess(){if(!this.selected)return;await this.call(()=>this.engine.room.act({type:'guess',target:this.selected,role:this.el('guess-role').value,team:this.el('guess-team').value}));}
 async send(){if(this.sending||this.composing)return;const field=this.el('draft'),text=field?.value.trim(),original=field?.value,mode=this.chatMode;if(!text)return;this.sending=true;const button=this.root.querySelector('[data-do=send]');if(button){button.disabled=true;button.textContent='전송 중…';}try{const result=await this.call(()=>this.engine.room.act({type:mode==='say'?'say':'interpret',text,slot:this.actionSlot||'small',clientMessageId:crypto.randomUUID()}));if(result?.ok){if(this.el('draft')?.value===original){this.draft='';this.el('draft').value='';}if(mode==='say'){if(this.feedTab==='actions')this.feedTab='story';this.chatToBottom=true;}}}finally{this.sending=false;this.render();}}
 async submitTrial(){if(this.filing||!this.trialOpen)return;const reason=this.el('reason')?.value.trim()||'',target=this.el('accused')?.value,facts=[...(this.trialFacts||[])];if(!reason)return this.toast('재판을 신청하는 이유를 적어 주세요.');if(facts.length>5)return this.toast('근거는 최대 다섯 개 선택하세요.');this.trialReason=reason;this.trialTarget=target;this.filing=true;const button=this.root.querySelector('[data-do=file]');if(button){button.disabled=true;button.textContent='신청을 보내는 중…';}try{const result=await this.action({type:'file',target,reason,facts},'big');if(result?.ok)this.trialOpen=null;return result;}finally{this.filing=false;if(button?.isConnected){button.disabled=false;button.textContent='재판 신청하기';}this.render();}}

 photoView(photo){if(!photo)return '<p>보관한 사진이 없습니다.</p>';const place=C.places[photo.place],V=globalThis.NoirVisuals||(typeof require==='function'?require('./03Visuals.js'):null);const frames=photo.frames||[];return `<figure class="press-photo">${frames.length?frames.map(f=>`<div class="press-photo-image scene-${place.photo}">${V.frame(f,photo.subjects)}</div>`).join(''):`<div class="press-photo-image scene-${place.photo}"><div class="photo-silhouettes">${photo.subjects.map(s=>`<div class="photo-subject ${s.condition.includes('쓰러져')?'fallen':''}"><span class="silhouette"></span><b>${E(s.name)}</b><small>${E(s.condition)}</small></div>`).join('')}</div></div>`}<figcaption><b>촬영 당시의 기록</b> · ${E(photo.time)} · ${E(place.name)} · 촬영 ${E(photo.byName)}</figcaption>${photo.moments.map(m=>`<p class="photo-moment">${this.richText(m)}</p>`).join('')}<small class="photo-note">${frames.length?'같은 시간대에 카메라에 잡힌 동작입니다. 장면 배열은 선후 순서를 뜻하지 않습니다.':'확인된 공격 동작이 없는 사진입니다. 기사 내용으로 동작을 덧그리지 않습니다.'}</small></figure>`;}
 verdictView(v){return `<div class="scene-image verdict-scene">${globalThis.NoirVisuals.verdict(v)}</div>`;}
 pressShelf(v){return `<h3>마을 신문</h3>${v.newspapers?.length?v.newspapers.slice().reverse().map(n=>`<article class="paper-link"><small>제${n.number}호 · ${E(n.time)}</small><button data-do="newspaper" data-id="${E(n.id)}">${E(n.headline)}</button><p>${this.personName(n.byName,n.by)} 발행</p></article>`).join(''):'<p>아직 발행된 신문이 없습니다.</p>'}${v.me.role==='reporter'?`<h3>내 사진 보관함</h3><p>촬영은 큰 행동입니다. 보관한 사진을 골라 다음 큰 행동으로 신문을 발행하세요.</p>${(v.me.photos||[]).map(p=>`<button class="photo-link" data-do="photo" data-id="${E(p.id)}">${E(p.time)} · ${E(C.places[p.place].name)} · ${E(p.subjects.find(x=>x.id===p.target)?.name||'현장')}</button>`).join('')||'<p>찍은 사진이 없습니다.</p>'}`:''}`;}
 paperDialog(n){if(!n)return '';return `<div class="overlay"><section class="newspaper" role="dialog" aria-modal="true" aria-labelledby="paper-title"><div class="paper-mast"><small>블랙 리지 · 제${n.number}호</small><h2>블랙 리지 주보</h2><span>${E(n.time)} · ${E(n.byName)} 발행</span></div><h1 id="paper-title">${E(n.headline)}</h1>${this.photoView(n.photo)}<section class="editorial"><small>기자가 쓴 기사 · 작성자의 주장</small><p>${this.richText(n.article)}</p></section><p class="paper-disclaimer">사진은 촬영 당시 보인 장면입니다. 제목과 기사 내용의 진실까지 보장하지 않습니다.</p><button data-do="close">신문 접기</button></section></div>`;}
 pressDialog(v){const draft=this.pressDraft;return `<div class="overlay" data-press-editor><section class="press-editor" role="dialog" aria-modal="true" aria-labelledby="press-title"><small>기자 · 큰 행동</small><h2 id="press-title">사진으로 신문 만들기</h2><label>실을 사진<select id="press-photo">${v.me.photos.map(p=>`<option value="${E(p.id)}" ${p.id===draft.photo?'selected':''}>${E(p.time)} · ${E(C.places[p.place].name)} · ${E(p.subjects.find(s=>s.id===p.target)?.name||'현장')}</option>`).join('')}</select></label><div data-photo-preview>${this.photoView(v.me.photos.find(p=>p.id===draft.photo))}</div><label>신문 제목<input id="press-headline" maxlength="80" value="${E(draft['press-headline'])}" placeholder="사진에서 무엇을 알리고 싶습니까?"></label><label>기사 본문<textarea id="press-article" rows="4" maxlength="500" placeholder="사진에 대한 설명이나 자신의 주장을 적으세요.">${E(draft['press-article'])}</textarea></label><p>선택한 사진과 기사는 이번 큰 행동 결과 때 모두에게 공개됩니다. 사진은 편집되지 않으며 기사와 구분됩니다.</p><div class="picker-footer"><button data-do="press-cancel">취소</button><button data-do="publish-paper" class="gold">신문 발행을 큰 행동으로 선택</button></div></section></div>`;}
 async submitPaper(){if(!this.pressOpen||this.publishing)return;const headline=this.el('press-headline').value.trim(),article=this.el('press-article').value.trim(),photo=this.el('press-photo').value;if(!headline||!article)return this.toast('신문 제목과 기사 본문을 적어 주세요.');this.publishing=true;try{const result=await this.action({type:'publish',photo,headline,article},'big');if(result?.ok)this.pressOpen=null;}finally{this.publishing=false;this.render();}}

 trialEvidenceDialog(v){const c=v.trial;if(!c)return '';return `<div class="overlay consent-overlay"><section role="dialog" aria-modal="true" aria-labelledby="case-title"><small>이번 재판에 공개된 기록</small><h2 id="case-title">재판 근거</h2><p>신청자 ${this.personName(v.people.find(p=>p.id===c.by)?.name,c.by)} → 대상 ${this.personName(v.people.find(p=>p.id===c.target)?.name,c.target)}</p>${(c.reasons||[{by:c.by,text:c.reason}]).map(x=>`<p><b>${E(v.people.find(p=>p.id===x.by)?.name)}</b>: ${E(x.text)}</p>`).join('')}<h3>제출한 근거 ${c.evidence?.length||0}건</h3>${c.evidence?.length?c.evidence.map(k=>`<blockquote><small>${E(k.time)} · ${E(k.source)} · ${k.kind==='claim'?'전해 들은 주장':k.kind==='observed'?'직접 목격':'조사·문서 기록'}</small><p>${this.richText(k.text)}</p></blockquote>`).join(''):'<p>첨부된 기록이 없습니다. 신청자의 주장을 바탕으로 변론과 증언을 확인하세요.</p>'}<p class="muted">제출됐다는 사실만으로 내용의 진실이 확정되지는 않습니다. 기록의 출처와 당사자의 설명을 함께 확인하세요.</p><button data-do="close">닫기</button></section></div>`;}
 async action(action,slot=this.actionSlot||'small'){const v=this.now.view;const result=await this.call(()=>this.engine.room.act({type:'action',action,slot,epoch:v.epoch,stage:v.stage}));if(result?.ok&&slot==='small')this.setSlot('big');if(result?.ok&&slot==='big'){if(action.type==='file'){this.tab='self';this.render();this.toast('재판 신청을 선택했습니다. 선택을 마치면 함께 접수하고, 결과 이야기 뒤에 동의 창이 열립니다.');}else this.toast(this.describe(action,v)+' 선택됨 · 모두의 선택이 끝나면 함께 처리합니다.');}return result;}
 storyShelf(v){const s=v.story;if(!s)return '<p>이어지는 사건 기록이 없습니다.</p>';return `<h3>내가 접한 사건</h3><p class="muted">직접 본 장면과 들은 후속 내용입니다. 다른 곳에서 생긴 일을 자동 공개하지 않습니다.</p>${s.journal.map(e=>`<article class="personal-lead"><small>${E(C.places[e.place]?.name)} · ${E(e.status)}</small><b>${this.richText(e.title)}</b>${e.result?`<p>${this.richText(e.result)}</p>`:''}</article>`).join('')||'<p>장소를 방문하거나 현장의 사람에게 말을 걸면 기록이 남습니다.</p>'}${s.npcs.length?'<h3>지금 보이는 NPC</h3>'+s.npcs.map(n=>`<p>${E(n.name)} · ${n.hp===0?'사망':n.bleeding?'출혈 중':n.hp<10?'부상':'활동 중'}</p>`).join(''):''}${s.stock!==null?`<p>진료소 붕대 · ${s.stock}개</p>`:''}${s.papers.length?'<h3>회관에 붙은 종이</h3>'+s.papers.map(a=>`<p>${this.richText(a.headline)}</p>`).join(''):''}${s.artifacts.length?'<h3>내가 보관한 현장 물건</h3>'+s.artifacts.map(a=>`<article><b>${E(a.title)}</b><p>${this.richText(a.text)}</p></article>`).join(''):''}`;}
 npcButtons(v){return (v.npcOptions||[]).length&&v.me.hp>0?'<div class="npc-talks"><button data-do="npc-menu">현장에서 말 걸기</button></div>':'';}
 async click(e){const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const a=b.dataset.do,r=this.engine.room,v=this.now?.view;if(a==='npc-menu'){this.overlay=`<div class="overlay"><section role="dialog" aria-modal="true"><h2>현장에서 말 걸기</h2><p>같은 장소에서 듣는 말입니다. 큰·작은 행동을 쓰지 않습니다.</p><select id="npc-topic" aria-label="물을 내용">${v.npcOptions.map(o=>`<option value="${E(o.topic)}">${E(o.label)}</option>`).join('')}</select><button data-do="npc-send">묻기</button><button data-do="close">닫기</button></section></div>`;this.render();return;}if(a==='npc-send'){const topic=this.el('npc-topic')?.value;this.overlay=null;if(topic)await this.call(()=>r.act({type:'npc-talk',topic}));this.render();return;}if(a==='npc-talk'){await r.act({type:'npc-talk',topic:b.dataset.topic});return;}if(a==='hazard'){await r.act({type:'hazard',choice:b.dataset.choice});return;}if(a==='sound'){await this.sound.toggle();this.render();return;}if(a==='tab'){this.tab=b.dataset.tab;this.render();return;}if(a==='composition'){this.overlay=this.compositionDialog(v);this.render();return;}if(a==='person'){this.selected=b.dataset.id;this.feedTab='person';this.render();const box=this.el('story-scroll');if(box)box.scrollTop=0;return;}
 if(['create','solo','join'].includes(a)){this.name=this.el('name').value.trim();if(!this.name)return this.toast('이름을 입력해 주세요.');localStorage.setItem('trpg:name',this.name);const count=Number(this.el('count').value),code=this.el('code').value;b.disabled=true;const ans=await this.call(()=>a==='join'?r.join(code,this.name):r.create(this.name));if(ans?.ok&&a==='solo')for(let i=1;i<count;i++)await this.call(()=>r.addBot());return;}
 if(a==='add')return this.call(()=>r.addBot());if(a==='remove')return this.call(()=>r.removeBot());if(a==='start')return this.call(()=>r.start());if(a==='leave'){if(v&&!v.result){this.overlay='<div class="overlay"><div><h2>판에서 나갑니까?</h2><p>다른 주민의 판은 계속됩니다.</p><button data-do="leave-confirm">나가기</button><button data-do="close">계속하기</button></div></div>';this.render();return;}await r.leave();this.now=null;this.render();return;}if(a==='leave-confirm'){await r.leave();this.overlay=null;this.now=null;this.render();return;}if(a==='close'){this.overlay=null;this.render();return;}
 if(a==='scene-next'){const next=v.sceneGuide?.options[Number(b.dataset.index)];if(next){this.setSlot(next.slot,false);await this.action({...next.action,label:next.label},next.slot);}return;}if(a==='scene-choice'){const choice=this.optionsBySlot[b.dataset.slot][Number(b.dataset.index)];this.actionPicker={type:'scene',sceneKey:choice.sceneKey,eventId:choice.eventId,pathIndex:choice.pathIndex,epoch:v.epoch,stage:v.stage,slot:b.dataset.slot};this.render();return;}if(a==='switch-slot'){this.setSlot(b.dataset.slot);return;}
 if(a==='press-cancel'){this.pressOpen=null;this.render();return;}if(a==='publish-paper')return this.submitPaper();if(a==='newspaper'){this.overlay=this.paperDialog(v.newspapers.find(x=>x.id===b.dataset.id));this.render();return;}if(a==='photo'){const photo=v.me.photos.find(x=>x.id===b.dataset.id);this.overlay=`<div class="overlay"><section class="newspaper" role="dialog" aria-modal="true" aria-label="보관한 사진"><h2>보관한 사진</h2>${this.photoView(photo)}<button data-do="close">닫기</button></section></div>`;this.render();return;}if(a==='action-group'&&b.dataset.type==='publish'){this.pressOpen={epoch:v.epoch};this.pressDraft={photo:v.me.photos[0]?.id,'press-headline':'','press-article':''};this.render();return;}if(a==='action-group'){const opts=(this.options||[]).filter(x=>x.type===b.dataset.type);if(!opts.length||v.ready)return;if(opts.length===1&&!['move','attack','give','bandage','heal','jail','recruit','persuade','investigate','buy','hide','evidence','observe','photograph'].includes(opts[0].type))return this.action(opts[0]);this.actionPicker={type:b.dataset.type,epoch:v.epoch,stage:v.stage,slot:this.actionSlot};this.render();return;}
 if(a==='cancel-picker'){this.actionPicker=null;this.render();return;}
 if(a==='submit-picker'){const q=this.actionPicker;if(!q||q.epoch!==v.epoch||q.stage!==v.stage||v.ready){this.actionPicker=null;this.render();return;}const chosen=q.type==='scene'?this.pickerChoices()[Number(q.sceneChoice)||0]:this.pickerChoices().find(x=>['target','place','weapon','request'].every(k=>!x[k]||x[k]===q[k]));if(!chosen)return;this.actionPicker=null;await this.action(chosen,q.slot);this.render();return;}
 if(a==='archive'){const entries=v.feed.filter(e=>e.i<v.chapter.from);this.overlay=`<div class="overlay"><section class="record-archive" role="dialog" aria-modal="true" aria-label="이전 기록"><h2>이전 이야기와 대화</h2>${entries.map(e=>this.line(e,true)).join('')}<button data-do="close">닫기</button></section></div>`;this.render();return;}if(a==='absent-people'){this.overlay=`<div class="overlay"><section role="dialog" aria-modal="true" aria-label="다른 주민 기록"><h2>현재 눈앞에 없는 주민</h2><p>마지막 목격 기록입니다. 이동했는지 숨어 있는지는 이 목록만으로 알 수 없습니다.</p>${v.people.filter(p=>!p.here&&p.id!==v.me.id).map(p=>this.personCard(p,v.me)).join('')}<button data-do="close">닫기</button></section></div>`;this.render();return;}if(a==='feed-tab'){this.feedTab=b.dataset.tab;this.render();return;}if(a==='people-tab'){this.peopleTab=b.dataset.tab;this.render();return;}if(a==='typing-sound'){this.typingSound=!this.typingSound;localStorage.setItem('trpg:typing-sound',this.typingSound?'on':'off');this.render();return;}if(a==='reveal-text'){this.revealText();return;}if(a==='trial-open'){this.trialOpen={epoch:v.epoch};this.trialReason='';this.trialTarget=null;this.trialFacts=new Set();this.render();return;}if(a==='trial-cancel'){this.trialOpen=null;this.render();return;}if(a==='send')return this.send();if(a==='pick')return this.action(this.options[Number(b.dataset.index)]);if(a==='confirm')return this.action(v.me.proposal.proposal,v.me.proposal.slot);if(a==='file')return this.submitTrial();if(a==='trial-evidence'){this.overlay=this.trialEvidenceDialog(v);this.render();return;}if(a==='share'){const result=await this.call(()=>r.act({type:'share-record',fact:b.dataset.id,clientMessageId:crypto.randomUUID()}));if(result?.ok){if(this.feedTab==='actions')this.feedTab='story';this.chatToBottom=true;this.render();}return;}
 if(a==='consent-hide'){this.consentCollapsed=b.dataset.id;this.render();return;}if(a==='consent-show'){this.consentCollapsed=null;this.render();return;}if(a==='consent-yes'||a==='consent-no')return this.call(()=>r.act({type:'support',case:b.dataset.id,accept:a==='consent-yes'}));if(a==='ready')return this.call(()=>r.act({type:'ready'}));if(a==='defend')return this.call(()=>r.act({type:'reaction',defense:b.dataset.defense}));if(a==='support')return this.call(()=>r.act({type:'support',case:b.dataset.id}));if(a==='vote')return this.call(()=>r.act({type:'vote',vote:b.dataset.vote}));if(a==='accept'||a==='reject')return this.call(()=>r.act({type:'offer',offer:b.dataset.id,accept:a==='accept',fact:this.offerFacts?.[b.dataset.id]||this.el('offer-'+b.dataset.id)?.value}));if(a==='save-will')return this.call(()=>r.act({type:'will',text:this.el('will').value}));if(a==='will'){const p=v.people.find(p=>p.id===b.dataset.id);this.overlay=`<div class="overlay"><div><small>남겨진 글</small><h2>${E(p.name)}의 유언</h2><p class="will-text">${this.richText(p.will||'남긴 유언이 없습니다.')}</p><button data-do="close">닫기</button></div></div>`;this.render();return;}if(a==='again'){this.dismissEnd=false;this.will=undefined;return this.call(()=>r.reopen());}if(a==='dismiss-end'){this.dismissEnd=true;this.root.querySelector('.ending')?.remove();return;}
 }
 tick(){this.acknowledgeStory();if(this.el('chat-clock')){const left=Math.max(0,Math.ceil(this.engine.room.left()||0));const read=['opening','clash','result','summons','decision'].includes(this.now?.view?.stage);const step=this.now?.view?.readingStep;this.el('chat-clock').textContent=step==='text'?'이야기 출력 중 · 시간 정지':step==='hold'?'읽기 여유 '+left+'초':(read?'읽는 시간 ':'남은 시간 ')+Math.floor(left/60)+':'+String(left%60).padStart(2,'0');this.el('chat-clock').classList.remove('urgent');}if(this.el('elapsed')){const t=this.now?.view?.elapsed||0;this.el('elapsed').textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;}}
}
WebEngine.define('TRPGUI',UI,'script');})();
